def seed_dynamic_sections(apps, schema_editor):
    Step = apps.get_model("core", "HowItWorksStep")
    for step in Step.objects.all():
        if (getattr(step, "fallback_image", "") or "").strip():
            continue
        order = int(step.sort_order or 0)
        if 1 <= order <= 6:
            step.fallback_image = f"{order:02d}"
            step.save(update_fields=["fallback_image"])

    from core.marketing import seed_default_footer, seed_default_hero_goals, seed_default_logo_chips

